    fprintf(f, "%s\n", x->frames[i]);
  }
  fclose(f);
  for (i = 0; i < x->nsel; i++) {
    strncpy(sel[i].bid, x->sel_bid[i], 31);
    strncpy(sel[i].host, x->sel_host[i], 63);
