  if (n_credit(x->out, sel, x->nsel) != 0) {
    return 1;
  }
  snprintf(path, sizeof(path), "%s/ok.mark", x->out);
  f = fopen(path, "w");
  if (!f) {
    return 1;
  }
  fputs("ok\n", f);
  fclose(f);
  return 0;
